"""Full initial-screen interpretation; only called after summarize's raw audit."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent

def render():
    meta=json.loads((HERE/'report/metadata.json').read_text());views=json.loads((HERE/'report/leaders.json').read_text());q=json.loads((HERE/'report/quality.json').read_text())
    def record(xs):
        return 'none'if not xs else '; '.join(f"{x['filter']}@{x['actual_bpk']:.5g} bpk, {x['latency_ns']:.5g} ns"for x in xs)
    lines=['# K12 initial bulk training screen','', 'This is the complete fixed seed 42 screen: 26 cases, 296 rows, two public query contracts, and every planned allocation. It is not a held-out or global-fastest result. The following counts select the fastest currently eligible K12 allocation in each of the 72 prespecified size/batch/cap/FPR/metric views; ties and unavailable comparisons remain explicit.','', '| Comparison | Wins | Losses | Ties | K12 ineligible | No eligible comparable rival |','|---|---:|---:|---:|---:|---:|']
    for kind,values in meta['summary'].items():lines.append('| '+kind+' | '+' | '.join(str(values[k])for k in['win','loss','tie','candidate_ineligible','no_comparable'])+' |')
    lines+=['','[The frozen registry](../2026-10-29-four-sector-range12-screen/registry.json) contains20 retained external API configurations, four production layouts, optional Range and K12. It is a previously selected strong shortlist, not every external configuration investigated in this project. [All raw commands and hashes](../2026-10-29-four-sector-range12-screen/screening/results-v1/metadata.json) and the [predata analysis rules](../2026-10-29-four-sector-range12-screen/screening/ANALYSIS_RULES.json) remain available.','','K12 quality is reported once per new size/allocation bitmap, with each 2^24-negative sample kept separate. Reusing the bitmap across two batch sizes does not increase sample size. Wilson 95% upper endpoints determine the three current-seed gates; they are finite-sample evidence rather than universal true-FPR guarantees.','', '| Keys | Actual bpk | Backing bytes | False positives / negatives | Upper, percent | Pass1% /0.1% /0.01% |','|---:|---:|---:|---:|---:|---|']
    for row in q['mapping_records']:
        if row['candidate']:lines.append(f"| {row['keys']} | {row['actual_bpk']} | {row['filter_bytes']} | {row['false_positives']} / {row['negatives']} | {100*row['wilson95_high']:.8f}% | {row['passes_1pct']} / {row['passes_0_1pct']} / {row['passes_0_01pct']} |")
    lines+=['','Every view below includes all smaller actual allocations under the cap. The existing optional Range API and K12 experimental mapping are separate from production and from external libraries. The best retained-project column compares the faster eligible production or optional-Range configuration. No old throughput is imported.','', '| Keys | Batch | Cap bpk | FPR ceiling | Contract | Best K12 | Best external | K12/ext outcome (ext/K12) | Best retained project | K12/project outcome (project/K12) |','|---:|---:|---:|---:|---|---|---|---|---|---|']
    for row in views:
        def outcome(key):
            entry=row[key];return entry['outcome']if entry['ratio']is None else f"{entry['outcome']} ({entry['ratio']:.5g}×)"
        lines.append(f"| {row['keys']} | {row['batch']} | {row['cap_bpk']} | {100*row['fpr_ceiling']:.3g}% | {row['metric']} | {record(row['winners']['K12_experiment'])} | {record(row['winners']['external'])} | {outcome('K12_vs_external')} | {record(row['best_retained_projects'])} | {outcome('K12_vs_retained')} |")
    lines+=['','The full tables retain 5,328 individual allocation alternatives and 216 K12 alternatives, including byte/quality failures, every loss, exact tie and no-comparable case. `leaders.json` retains four ownership-class leaders and every exact tie. PageBloom is a public raw-byte API; its prehashed timing is invalid and excluded only from that query contract. Common-hash-plus-bulk measures the common hash for prehash APIs and the public raw-key API for Page, with that upstream distinction preserved.','', 'The actual backing-byte cap includes reported allocation padding, while explicit filter-build and harness scratch are retained separately. Construction metrics are NaN: one full bitmap build precedes the query timers, so this screen makes no build-speed claim. Pure and hash+query phases use six balanced repetitions; each full trial vector/min/max remains in raw rows. The one seed-derived filter order per case and allocation/address placement are not independent causal controls.','', 'All 284 retained control rows reproduce the 142 committed prior geometries at both batches, including checksums and mixed/calibration counts. The six K12 quality streams are new; their earlier accuracy pilot used a different input interval and is not an exact-count reproduction. Relevant older borderline quality outcomes remain context only and do not replace the current-seed ranking gates.','', f"Source `{meta['source_commit']}`, complete raw `{meta['raw_commit']}`. The actual caller binary and compiler dependency closure passed native, AVX2 and ASan preflight before this screen. Measurement uses CPU3/socket1 affinity with a whole-matrix lock and no explicit NUMA memory binding. No source, allocation, filter or quality rule changed after the screen began.",'']
    return '\n'.join(lines)
if __name__=='__main__':(HERE/'REPORT.md').write_text(render())
